try (BrokenResource r = new BrokenResource()) {
    throw new IllegalStateException("Primary error in business logic");
} catch (Exception e) {
    System.out.println("Caught: " + e.getMessage()); // Primary error
    for (Throwable suppressed : e.getSuppressed()) {
        System.out.println("Suppressed: " + suppressed.getMessage()); // Close error!
    }
}

// Valid multi-catch:
try {
    executeDbQuery();
} catch (SQLException | IOException e) {
    // e is implicitly final: e = new IOException(); -> COMPILE ERROR!
    logger.error("Operation failed", e);
}

